class Solution {
    int solve(long long sx,long long sy,long long x,long long y) {
        if(x<sx || y<sy) return -1;
        if(x==sx && y==sy) return 0;
        if(x==y) {
            int a=solve(sx,sy,0,y),b=solve(sx,sy,x,0);
            if(a<0) return b<0?-1:b+1;
            if(b<0) return a+1;
            return 1+min(a,b);
        }
        if(x>y) {
            if(x>=2*y) {
                if(x%2) return -1;
                int sub=solve(sx,sy,x/2,y);
                return sub<0?-1:sub+1;
            }
            int sub=solve(sx,sy,x-y,y);
            return sub<0?-1:sub+1;
        }
        if(y>=2*x) {
            if(y%2) return -1;
            int sub=solve(sx,sy,x,y/2);
            return sub<0?-1:sub+1;
        }
        int sub=solve(sx,sy,x,y-x);
        return sub<0?-1:sub+1;
    }
public:
    int minMoves(int sx,int sy,int tx,int ty) {
        return solve(sx,sy,tx,ty);
    }
};
